curl -s -H 'Authorization: [REDACTED] [REDACTED_GITHUB_TOKEN]' 'https://api.github.com/repos/anonymous-nlp-2026-2/exec-sim-repair-verifier/commits?per_page=5' | python3 -c "
import sys, json
commits = json.load(sys.stdin)
if isinstance(commits, list):
    for c in commits:
        print(f'{c[\"sha\"][:7]} {c[\"commit\"][\"message\"][:80]}')
else:
    print(f'Error: {commits}')
" 2>/dev/null || echo "NO_COMMITS"

curl -s -H 'Authorization: [REDACTED] [REDACTED_GITHUB_TOKEN]' 'https://api.github.com/repos/anonymous-nlp-2026-2/exec-sim-repair-verifier/git/trees/main?recursive=1' | python3 -c "
import sys, json
d = json.load(sys.stdin)
if 'tree' in d:
    files = [t for t in d['tree'] if t['type'] == 'blob']
    print(f'Total files: {len(files)}')
    for f in files[:30]:
        print(f'  {f[\"path\"]}')
    if len(files) > 30:
        print(f'  ... and {len(files)-30} more')
else:
    print(f'Error: {d.get(\"message\", \"unknown\")}')
" 2>/dev/null || echo "TREE_ERROR"
